request_template.query:
query CustomerRatingCard_Init($skuId: String!) {
  ...CustomerRatingCard_Fragment
}

fragment CustomerRatingCard_Fragment on Query {
  productBySkuId(skuId: $skuId) {
    skuId
    reviewInfo {
      averageRating
      recommendedPercent
      reviewCount
      starRatingDistribution {
        count
        percent
        value
        __typename
      }
      __typename
    }
    __typename
    openBoxCondition
  }
  __typename
}

query Ai_Review_Summary_Init($skuId: String!) {
  ...AiReviewSummary_Fragment
}

fragment AiReviewSummary_Fragment on Query {
  productBySkuId(skuId: $skuId) {
    reviewInfo {
      reviewSummary
      __typename
    }
    __typename
    skuId
    openBoxCondition
  }
  __typename
}

query CustomerReviewList_Init($skuId: String!, $onlyIfRelated: Boolean = true) {
  ...CustomerReviewList_Fragment
}

fragment CustomerReviewList_Fragment on Query {
  productBySkuId(skuId: $skuId) {
    reviews(filter: {page: 1, pageSize: 3, sortBy: BEST_MATCH}) {
      results {
        badges {
          code
          description
          name
          __typename
        }
        daysOfOwnership
        id
        images {
          id
          piscesUrl
          __typename
        }
        rating
        submissionTime
        text
        title
        userNickname
        reviewedProduct(onlyIfRelated: $onlyIfRelated) {
          dotComDisplayStatus
          name {
            short
            __typename
          }
          skuId
          url {
            relativePdp
            __typename
          }
          __typename
          openBoxCondition
        }
        __typename
      }
      __typename
    }
    __typename
    skuId
    openBoxCondition
  }
  __typename
}
